// v0.18.75: every SOL figure is a straight line in size and cost (size × (x·(1−cost) − 1)), so the page gets each one as
// [per-SOL at 0% cost, change per unit of cost] and works out any size / cost itself — instant buttons, no server trip.
const MONEY = new Set(["net", "gross", "net24", "best", "worst", "p1", "p2"]), CURVES = new Set(["curve", "histCurve"]);
const per1 = (v) => Math.round(v * 1000) / 1e6; // computed at 1000 SOL so the 3-decimal rounding inside snapshot() is 0.000001 per SOL
let LIN = { at: 0, body: null }; // shared by every open tab for 2 s
export function linSnapshot() {
  const a = snapshot(1000, 0), b = snapshot(1000, 1);
  const walk = (x, y, k) => {
    if (typeof x === "number") return MONEY.has(k) && typeof y === "number" ? { $: [per1(x), per1(y - x)] } : x;
    if (Array.isArray(x)) return CURVES.has(k) ? x.map((pt, i) => [pt[0], [per1(pt[1]), per1(((y && y[i]) ? y[i][1] : pt[1]) - pt[1])]]) : x.map((v, i) => walk(v, y ? y[i] : undefined, k));
    if (x && typeof x === "object") { const o = {}; for (const kk of Object.keys(x)) o[kk] = walk(x[kk], y ? y[kk] : undefined, kk); return o; }
    return x;
  };
  const out = walk(a, b, ""); out.lin = 1; return out;
}

